const p=((($json.period)||'month')+'').toLowerCase().trim();
let begin;
const now=new Date();
if(p==='today'){ begin=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate())).toISOString(); }
else if(p==='week'){ begin=new Date(now.getTime()-7*24*3600*1000).toISOString(); }
else { begin=new Date(now.getTime()-30*24*3600*1000).toISOString(); }
return [{json:{period:(p==='today'||p==='week')?p:'month', begin_time:begin}}];

const period=$('BuildQuery').first().json.period;
const d=$json||{};
if(d.errors&&d.errors.length) return [{json:{summary:'Square error reading sales: '+d.errors.map(e=>e.detail||e.code).join('; ')}}];
const pays=d.payments||[];
let cents=0,n=0;
const byDay={};
for(const p of pays){
  if(p.status==='COMPLETED'){
    n++;
    const amt=(p.amount_money&&p.amount_money.amount)||0;
    cents+=amt;
    const day=(p.created_at||'').slice(0,10);
    if(day){ byDay[day]=(byDay[day]||0)+amt; }
  }
}
const label=period==='today'?'Today':(period==='week'?'This week':'This month');
const more=d.cursor?' (first 100 payments)':'';
const daily=Object.keys(byDay).sort().map(date=>({date, total:Number((byDay[date]/100).toFixed(2))}));
return [{json:{summary:`${label}: ${n} sale${n===1?'':'s'}, $${(cents/100).toFixed(2)} collected${more}.`, daily}}];
